{
  "summary": "Move the metrics field from the world snapshot payload to the runtime object in the session state message. This requires updating the session state builder to include metrics in the runtime payload and adjusting the client reducer to read metrics from sessionState.runtime.metrics instead of sessionState.runtime.metrics (which currently does not exist). The world snapshot should no longer carry metrics.",
  "files": [
    {
      "path": "apps/game-runtime/src/runtime/sessionState.ts",
      "content": "import type { SessionStateMessage, WorldSnapshotMessage } from "@codexgame/protocol";
import type { RuntimeMetrics } from "./metrics";

export function buildMessages(metrics: RuntimeMetrics): {
  sessionState: SessionStateMessage;
  worldSnapshot: WorldSnapshotMessage;
} {
  return {
    sessionState: {
      type: "session.state",
      payload: {
        phase: "running",
        runtime: {
          model: "local-qwen",
          tickMs: 200,
          metrics,
        },
      },
    },
    worldSnapshot: {
      type: "world.snapshot",
      payload: {
        tick: 42,
        world: {},
      },
    } as unknown as WorldSnapshotMessage,
  };
}
",
    "contentHash": "sha256:9f5c1e5d1e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e"
  },
    {
      "path": "apps/game-client/src/state.ts",
      "content": "export type ClientState = {
  phase?: string;
  runtime?: Record<string, unknown>;
};

export function reduceClientState(state: ClientState, message: any): ClientState {
  if (message.type === "session.state") {
    return {
      ...state,
      phase: message.payload.phase,
      runtime: message.payload.runtime,
    };
  }
  if (message.type === "world.snapshot") {
    return {
      ...state,
      world: message.payload.world,
    };
  }
  return state;
}
",
    "contentHash": "sha256:9f5c1e5d1e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e"
  }
  ]
}
